INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l01',1,1,'Excuse me, is this your phone?','打扰一下，这是你的手机吗？','Is this...? 一般疑问句 · this · my/your · Excuse me','西雅图一家咖啡店','{"q":"Whose phone is it?","options":["选项：","Tyler''s","Emma''s","The waiter''s"],"answer_index":2}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l02',1,2,'Here''s my ticket','给您我的取车票','Here''s... / Here are... · 祈使句请求 · my/your + 名词 · I''m sorry（道歉）','酒店门口代客泊车（valet parking）','{"q":"What color is David''s car?","options":["Gray","Blue","Black"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l03',1,3,'This is my friend Diego','这是我的朋友迭戈','冠词 a/an · 国籍表达 · This is + 人（介绍） · He''s/She''s','社区街区派对（block party）','{"q":"What is Diego''s job?","options":["A teacher","An engineer","A nurse"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l04',1,4,'What''s your job?','你是做什么工作的？','Are you...? 问答 · What''s your job? · a/an + 职业 · 国籍问答','社区大学晚间英语班第一天','{"q":"What is Sofia''s job?","options":["A nurse","An electrician","A teacher"],"answer_index":0}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l05',1,5,'How are you today?','你今天好吗？','How are you? / How''s...? 问答 · 形容词作表语 · 美式寒暄告别语','清晨遛狗偶遇邻居','{"q":"How is Carlos''s puppy?","options":["Sick","Happy","Tired"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l06',1,6,'Whose mug is this?','这是谁的马克杯？','Whose...? · 名词所有格 ''s · his/her · that','办公室茶水间认领马克杯','{"q":"Whose mug is it?","options":["Amanda''s","Tina''s","Chris''s"],"answer_index":2}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l07',2,7,'What color is your favorite?','你最喜欢什么颜色？','What color...? 问答 · 颜色形容词作定语（a green T-shirt） · What size...?','商场买 T 恤','{"q":"What is Lily''s favorite color?","options":["Blue","Green","Orange"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l08',2,8,'Are these your boxes?','这些是你的箱子吗？','名词复数（-s / -es） · these/those · Are these...? — Yes, they are. · they','搬家日，朋友帮忙核对物品','{"q":"Whose chairs are those?","options":["Sara''s","Emma''s","Jake''s"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l09',2,9,'These are my cousins','这些是我的表亲们','This is / These are + 人（介绍单复数） · we/they + are · 复数职业 · you guys','感恩节家庭聚餐','{"q":"What is Aunt Carol''s job?","options":["A cook","A doctor","A teacher"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l10',2,10,'What''s the matter?','你怎么了？','What''s the matter? 问答 · be + 状态形容词（tired/thirsty/hungry） · 程度词 so/really · Me too','徒步之后的加油站便利店','{"q":"How does Zoe feel?","options":["Happy","Tired and thirsty","Hungry only"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l11',2,11,'Which one?','哪一本？','Which...? 问句 · 替代词 one · this one / that one','公共图书馆找书','{"q":"What color is the book?","options":["Red","Blue","Green"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l12',2,12,'Which ones?','哪几副？','Which ones? 复数替代 · these/those + 形容词 + ones · 介词 on/in · 宾语代词 them 初步','眼镜店挑太阳镜','{"q":"Which sunglasses are on sale?","options":["The black ones","The brown ones","The blue ones"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l13',3,13,'Is there a pan here?','这里有平底锅吗？','There is... / Is there...? 问答 · 方位介词 in / on / under · There it is.','新公寓厨房，朋友帮忙做塔可','{"q":"Where is the salt?","options":["On the counter","In the cabinet","Under the coffee maker"],"answer_index":2}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l14',3,14,'Are there any old bikes?','有旧自行车吗？','There are... / Are there...? 问答 · some / any · 介词 behind','收拾车库，准备车库旧物出售','{"q":"Where are the bikes?","options":["On the shelf","Behind the boxes","Under the table"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l15',3,15,'Come in!','快请进！','祈使句（Come in / Sit down / Have some... / Try...） · must + 动词原形 · please','招待来家做客的朋友','{"q":"What is fresh?","options":["The cookies","The lemonade","The brownies"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l16',3,16,'What are you doing?','你在做什么？','现在进行时（单数）be + V-ing · What are you doing? 问答 · -ing 拼写规则','和奶奶视频通话','{"q":"What is Dad doing?","options":["Making dinner","Watching the game","Sleeping"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l17',3,17,'What''s happening at the park?','公园里在发生什么？','现在进行时（复数）They are + V-ing · What''s the weather like? 天气问答 · What''s happening?','周六早晨的公园（电话邀约）','{"q":"What''s the weather like?","options":["Rainy","Sunny and warm","Cloudy"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l18',3,18,'Welcome to Main Street','欢迎来到主街','there be + 现在进行时综合运用 · 物主代词 their · 地点介词综合（near / next to / behind / over there）','带表哥逛小镇主街与农夫集市','{"q":"What day is the farmers market?","options":["Saturday","Sunday","Monday"],"answer_index":0}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l19',4,19,'We''re going to have a BBQ!','我们要办烧烤啦！','be going to + 动词原形（计划打算） · Are you going to...? · It''s going to be...','邀请朋友参加周末后院烧烤','{"q":"What is Lisa going to make?","options":["Burgers","Potato salad","Brownies"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l20',4,20,'Don''t drop it!','别摔了！','否定祈使句 Don''t + 动词原形 · 祈使句扩展（Hurry / Move / Turn off） · 进行时复习','给妈妈布置生日惊喜派对','{"q":"What is Alex carrying?","options":["The banner","The balloons","The cake"],"answer_index":2}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l21',4,21,'Is there any juice?','还有果汁吗？','可数 vs 不可数名词 · 不可数名词 + some/any（There''s some milk / Is there any juice?） · a lot of','查冰箱列购物清单','{"q":"Is there any juice in the fridge?","options":["Yes, there is.","No, there isn''t.","We don''t know."],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l22',4,22,'Can you play the drums?','你会打鼓吗？','can / can''t + 动词原形（能力） · Can you...? 问答 · play the + 乐器','车库乐队招新','{"q":"Can Chloe play the guitar?","options":["Yes, she can.","No, she can''t.","We don''t know."],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l23',4,23,'Can you help me?','能帮我个忙吗？','Can you...?（礼貌请求） · 宾语代词全表（me/him/her/it/us/them） · Give it to...','办公室请同事帮忙','{"q":"Who is the box for?","options":["Sam","Kim","Dana"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l24',4,24,'Do you like sweet drinks?','你喜欢甜的饮品吗？','一般现在时 like/want（首次引入 do 助动词） · Do you...? — Yes, I do. / No, I don''t. · don''t + 动词原形 · A or B? 选择问句','咖啡店点单','{"q":"Rosa''s latte—hot or iced?","options":["Hot","Iced","Warm"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l25',5,25,'Let''s order pizza!','咱们点披萨吧！','like / love / don''t like（好恶程度） · not ... at all · Let''s + 动词原形 · What do you like?','室友商量披萨配料','{"q":"Emily says \"I don''t like ___ at all.\"","options":["Olives","Mushrooms","Pepperoni"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l26',5,26,'I usually get up at six','我通常六点起床','频度副词 always / usually / sometimes / never 及位置 · every + 时间 · 一般现在时表习惯','同事聊晨间习惯','{"q":"Ken usually gets up at ___.","options":["Five","Six","Seven"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l27',5,27,'Does he cook?','他会做饭吗？','第三人称单数动词 -s / -es · have → has · Does he/she...? — Yes, he does. · doesn''t + 动词原形','聊新室友','{"q":"Marco works at ___.","options":["A coffee shop","An animal hospital","A middle school"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l28',5,28,'The Carter family','卡特一家','三单综合运用 · 复数主语不加 -s 对照 · do homework · 时间表达（at night / in the morning / on Fridays）','一个美国家庭的一天（本课程首篇叙述体课文）','{"q":"What is Mr. Carter''s job?","options":["A teacher","A firefighter","A cashier"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l29',5,29,'Today is different','今天不一样','一般现在时（习惯） vs 现在进行时（此刻/这阵子）对比 · 信号词判断 · I usually..., but today I''m...','同事发现对方一反常态','{"q":"What is Molly drinking today?","options":["Coffee","Green tea","Soda"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l30',5,30,'Is that all?','就这些吗？','量词结构 a bag/box/bottle of · 结账三连（Is that all? / Anything else? / That''s it.） · Paper or plastic? · 价格口语读法','超市收银台结账','{"q":"Grace wants a bag of ___.","options":["Apples","Bananas","Cereal"],"answer_index":0}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
